<?php /* VIVA NOTE: Property image gallery and upload form. */ ?><div class="toolbar"><p>Property photo gallery · <?=e($property['title'])?></p><a href="<?=e(url('/property/show',['id'=>$property['property_id']]))?>">← Back</a></div>
<section class="panel"><h3>Upload a photo</h3><form method="post" action="<?=e(url('/property/photos/upload',['id'=>$property['property_id']]))?>" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><label>Photo (JPG, PNG, WebP; 5 MB max)<input name="photo" type="file" accept="image/png,image/jpeg,image/webp" required></label><label>Caption<input name="caption" maxlength="255"></label><button class="btn">Upload photo</button></form></section>
<div class="gallery"><?php foreach($photos as $photo):?><article class="photo-card"><img alt="<?=e($photo['caption']?:'Property photo')?>" loading="lazy" src="<?=e(url('/'.$photo['file_path']))?>"><p><?=e($photo['caption']?:'Property photo')?></p><form method="post" action="<?=e(url('/property/photos/delete',['id'=>$property['property_id']]))?>" data-confirm="Delete this photo?"><?=csrf_field()?><input type="hidden" name="photo_id" value="<?=e($photo['photo_id'])?>"><button class="btn small danger">Remove</button></form></article><?php endforeach;?><?php if(!$photos):?><p class="empty">No uploaded photos yet.</p><?php endif;?></div>
